#!/usr/bin/env bash

set -u
set -o pipefail

SCRIPT_DIR=$(cd "$(dirname "$0")" && pwd -P)
SCRIPT="$SCRIPT_DIR/../scripts/repository-bootstrap"
TEST_ROOT=$(mktemp -d "${TMPDIR:-/tmp}/repository-bootstrap-tests.XXXXXX")
FAKE_BIN="$TEST_ROOT/bin"
PASSED=0
FAILED=0
TOTAL=11
FAKE_ENTIRE_LOG="$TEST_ROOT/entire.log"

cleanup() {
  rm -rf "$TEST_ROOT"
}
trap cleanup EXIT

mkdir -p "$FAKE_BIN"
cat > "$FAKE_BIN/entire" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$FAKE_ENTIRE_LOG"
case "$1 $2" in
  "status --json")
    printf 'entire status is not read-only\n' >&2
    exit 97
    ;;
  "auth status")
    if [ "${FAKE_ENTIRE_AUTH:-logged-in}" = "logged-in" ]; then
      printf 'Logged in to test context\n'
    else
      printf 'Not logged in to test context\n'
    fi
    ;;
  "graph version")
    [ "${FAKE_GRAPH:-true}" = "true" ] && printf '0.4.0\n' || exit 1
    ;;
  *) exit 1 ;;
esac
EOF
chmod +x "$FAKE_BIN/entire"
export PATH="$FAKE_BIN:$PATH"
export FAKE_ENTIRE_LOG

pass() {
  PASSED=$((PASSED + 1))
  printf 'ok %d - %s\n' "$PASSED" "$1"
}

fail_test() {
  FAILED=$((FAILED + 1))
  printf 'not ok - %s: %s\n' "$1" "$2" >&2
}

assert_eq() {
  local expected="$1" actual="$2" message="$3"
  if [ "$expected" != "$actual" ]; then
    printf 'assertion failed: %s (expected=%s actual=%s)\n' "$message" "$expected" "$actual" >&2
    return 1
  fi
}

assert_contains() {
  local haystack="$1" needle="$2" message="$3"
  case "$haystack" in
    *"$needle"*) ;;
    *) printf 'assertion failed: %s (missing=%s)\n' "$message" "$needle" >&2; return 1 ;;
  esac
}

run_capture() {
  local output_file="$1"
  shift
  "$@" > "$output_file" 2>&1
  return $?
}

git_init_repo() {
  local repo="$1"
  mkdir -p "$repo"
  git -C "$repo" init -q -b main
  git -C "$repo" config user.name Test
  git -C "$repo" config user.email test@example.com
  git -C "$repo" config commit.gpgsign false
}

git_commit_file() {
  local repo="$1" name="${2:-README.md}"
  printf 'fixture\n' > "$repo/$name"
  mkdir -p "$repo/.entire"
  printf '{"enabled":true}\n' > "$repo/.entire/settings.json"
  git -C "$repo" add "$name"
  git -C "$repo" commit -q -m fixture
}

add_standard_remotes() {
  local repo="$1" name="$2"
  git -C "$repo" remote add origin "git@github.com:MuskanPaliwal/$name.git"
  git -C "$repo" remote add upstream "git@github.com:entireio/$name.git"
}

repo_snapshot() {
  local repo="$1"
  {
