    git --no-optional-locks -C "$repo" status --porcelain=v2 --branch 2>/dev/null || true
    git -C "$repo" rev-parse HEAD 2>/dev/null || true
  } | shasum -a 256 | awk '{print $1}'
}

index_hash() {
  local repo="$1" index
  index="$(git -C "$repo" rev-parse --absolute-git-dir)/index"
  shasum -a 256 "$index" | awk '{print $1}'
}

test_conventional_read_only_and_apply_guards() {
  local name="conventional read-only checks and guarded apply"
  local repo="$TEST_ROOT/conventional" out="$TEST_ROOT/conventional.json" plan="$TEST_ROOT/conventional.plan"
  git_init_repo "$repo"
  git_commit_file "$repo"
  add_standard_remotes "$repo" conventional
  local before after rc
  before=$(repo_snapshot "$repo")
  run_capture "$out" bash "$SCRIPT" check --repo "$repo" --format json
  rc=$?
  [ "$rc" -eq 3 ] || { fail_test "$name" "check exit was $rc"; return; }
  after=$(repo_snapshot "$repo")
  assert_eq "$before" "$after" "check must not mutate repository" || { fail_test "$name" "check mutated state"; return; }
  assert_eq "conventional" "$(jq -r '.repository.layout' "$out")" "layout" || { fail_test "$name" "wrong layout"; return; }
  assert_eq "false" "$(jq -r '.remotes.upstream.push_disabled' "$out")" "upstream initially pushable" || { fail_test "$name" "wrong upstream state"; return; }
  assert_contains "$(jq -r '.plan.decisions[]' "$out")" "adopt_entire_mirror" "mirror decision" || { fail_test "$name" "mirror decision absent"; return; }
  bash "$SCRIPT" plan --repo "$repo" > "$plan" || rc=$?
  assert_contains "$(cat "$plan")" "safe disable_upstream_push" "plan safe action" || { fail_test "$name" "safe action absent"; return; }
  before=$(repo_snapshot "$repo")
  if bash "$SCRIPT" apply --repo "$repo" --plan "$plan" --allow disable_upstream_push >/dev/null 2>&1; then
    fail_test "$name" "apply succeeded without --yes"; return
  fi
  after=$(repo_snapshot "$repo")
  assert_eq "$before" "$after" "failed apply must not mutate" || { fail_test "$name" "guard failure mutated"; return; }
  if bash "$SCRIPT" apply --repo "$repo" --plan "$plan" --yes >/dev/null 2>&1; then
    fail_test "$name" "apply succeeded without --allow"; return
  fi
  bash "$SCRIPT" apply --repo "$repo" --plan "$plan" --yes --allow disable_upstream_push >/dev/null 2>&1 || rc=$?
  assert_eq "DISABLED" "$(git -C "$repo" remote get-url --push upstream)" "upstream push disabled" || { fail_test "$name" "safe action not applied"; return; }
