esac
EOF
chmod +x "$FAKE_BIN/entire"
export PATH="$FAKE_BIN:$PATH"
export FAKE_ENTIRE_LOG

pass() {
  PASSED=$((PASSED + 1))
  printf 'ok %d - %s\n' "$PASSED" "$1"
}

fail_test() {
  FAILED=$((FAILED + 1))
  printf 'not ok - %s: %s\n' "$1" "$2" >&2
}

assert_eq() {
  local expected="$1" actual="$2" message="$3"
  if [ "$expected" != "$actual" ]; then
    printf 'assertion failed: %s (expected=%s actual=%s)\n' "$message" "$expected" "$actual" >&2
    return 1
  fi
}

assert_contains() {
  local haystack="$1" needle="$2" message="$3"
  case "$haystack" in
    *"$needle"*) ;;
    *) printf 'assertion failed: %s (missing=%s)\n' "$message" "$needle" >&2; return 1 ;;
  esac
}

run_capture() {
  local output_file="$1"
  shift
  "$@" > "$output_file" 2>&1
  return $?
}

git_init_repo() {
  local repo="$1"
  mkdir -p "$repo"
  git -C "$repo" init -q -b main
  git -C "$repo" config user.name Test
  git -C "$repo" config user.email test@example.com
  git -C "$repo" config commit.gpgsign false
}

git_commit_file() {
  local repo="$1" name="${2:-README.md}"
  printf 'fixture\n' > "$repo/$name"
  mkdir -p "$repo/.entire"
  printf '{"enabled":true}\n' > "$repo/.entire/settings.json"
  git -C "$repo" add "$name"
  git -C "$repo" commit -q -m fixture
}

add_standard_remotes() {
  local repo="$1" name="$2"
  git -C "$repo" remote add origin "git@github.com:MuskanPaliwal/$name.git"
  git -C "$repo" remote add upstream "git@github.com:entireio/$name.git"
}

repo_snapshot() {
  local repo="$1"
  {
    git -C "$repo" config --local --list | LC_ALL=C sort
    git --no-optional-locks -C "$repo" status --porcelain=v2 --branch 2>/dev/null || true
    git -C "$repo" rev-parse HEAD 2>/dev/null || true
  } | shasum -a 256 | awk '{print $1}'
}

index_hash() {
  local repo="$1" index
  index="$(git -C "$repo" rev-parse --absolute-git-dir)/index"
  shasum -a 256 "$index" | awk '{print $1}'
}

