  local seed="$TEST_ROOT/container-seed" container="$TEST_ROOT/container" bare="$TEST_ROOT/container/.bare" worktree="$TEST_ROOT/container/main"
  local out="$TEST_ROOT/container.json" canonical_worktree rc
  git_init_repo "$seed"
  git_commit_file "$seed"
  mkdir -p "$container"
  git clone -q --bare "$seed" "$bare"
  printf 'gitdir: ./.bare\n' > "$container/.git"
  git --git-dir "$bare" remote set-url origin git@github.com:MuskanPaliwal/container.git
  git --git-dir "$bare" remote add upstream git@github.com:entireio/container.git
  git --git-dir "$bare" config remote.upstream.pushurl DISABLED
  git --git-dir "$bare" worktree add -q "$worktree" main
  canonical_worktree=$(cd "$worktree" && pwd -P)
  run_capture "$out" bash "$SCRIPT" check --repo "$container" --format json --mirror-policy optional
  rc=$?
  [ "$rc" -eq 3 ] || { fail_test "$name" "check exit was $rc"; return; }
  assert_eq "bare-repository" "$(jq -r '.repository.layout' "$out")" "container layout" || { fail_test "$name" "wrong layout"; return; }
  assert_eq "true" "$(jq -r '.repository.requires_worktree' "$out")" "worktree requirement" || { fail_test "$name" "worktree not required"; return; }
  assert_eq "false" "$(jq -r '.repository.worktree_state_resolved' "$out")" "worktree-local facts unresolved" || { fail_test "$name" "local state marked resolved"; return; }
  assert_eq "$canonical_worktree" "$(jq -r '.repository.worktree_candidates[0]' "$out")" "candidate worktree" || { fail_test "$name" "candidate missing"; return; }
  assert_eq "MuskanPaliwal/container" "$(jq -r '.remotes.origin.identity' "$out")" "shared repository identity" || { fail_test "$name" "identity missing"; return; }
  assert_eq "null" "$(jq -r '.git.branch' "$out")" "current branch unresolved" || { fail_test "$name" "branch guessed"; return; }
  assert_eq "main" "$(jq -r '.git.default_branch' "$out")" "repository default branch" || { fail_test "$name" "default branch missing"; return; }
  assert_eq "null" "$(jq -r '.git.dirty' "$out")" "dirty state unresolved" || { fail_test "$name" "dirty state guessed"; return; }
  assert_eq "worktree-required" "$(jq -r '.entire.enabled_state' "$out")" "worktree-local state" || { fail_test "$name" "local state guessed"; return; }
  assert_eq "null" "$(jq -r '.entire.enabled' "$out")" "unknown enablement" || { fail_test "$name" "enablement guessed"; return; }
  assert_eq "null" "$(jq -r '.entire.runner_count' "$out")" "runner count unresolved" || { fail_test "$name" "runner count guessed"; return; }
  assert_eq "null" "$(jq -r '.entire.checkpoint_repo' "$out")" "checkpoint repository unresolved" || { fail_test "$name" "checkpoint repository guessed"; return; }
  assert_contains "$(jq -r '.plan.decisions[]' "$out")" "select_repository_worktree" "selection decision" || { fail_test "$name" "selection absent"; return; }
  pass "$name"
}

test_dirty_repository_preserved() {
  local name="dirty repository is reported and preserved"
  local repo="$TEST_ROOT/dirty" out="$TEST_ROOT/dirty.json" before after rc
  git_init_repo "$repo"
  git_commit_file "$repo"
  add_standard_remotes "$repo" dirty
  git -C "$repo" config remote.upstream.pushurl DISABLED
  printf 'changed\n' >> "$repo/README.md"
  printf 'untracked\n' > "$repo/notes.txt"
  before=$(repo_snapshot "$repo")
  run_capture "$out" bash "$SCRIPT" check --repo "$repo" --format json
  rc=$?
  [ "$rc" -eq 3 ] || { fail_test "$name" "check exit was $rc"; return; }
  assert_eq "true" "$(jq -r '.git.dirty' "$out")" "dirty fact" || { fail_test "$name" "dirty not reported"; return; }
  assert_contains "$(jq -r '.plan.decisions[]' "$out")" "preserve_dirty_worktree" "dirty decision" || { fail_test "$name" "decision absent"; return; }
  after=$(repo_snapshot "$repo")
  assert_eq "$before" "$after" "dirty files and index must be untouched" || { fail_test "$name" "state changed"; return; }
  pass "$name"
}

test_no_commit_repository() {
  local name="no-commit repository remains audit-only"
  local repo="$TEST_ROOT/no-commit" out="$TEST_ROOT/no-commit.json" rc
  git_init_repo "$repo"
  add_standard_remotes "$repo" no-commit
  git -C "$repo" config remote.upstream.pushurl DISABLED
  printf 'keep me\n' > "$repo/untracked.txt"
  run_capture "$out" bash "$SCRIPT" check --repo "$repo" --format json
  rc=$?
  [ "$rc" -eq 3 ] || { fail_test "$name" "check exit was $rc"; return; }
  assert_eq "false" "$(jq -r '.git.has_commits' "$out")" "has commits" || { fail_test "$name" "commit state wrong"; return; }
  assert_contains "$(jq -r '.plan.decisions[]' "$out")" "create_initial_commit" "initial commit decision" || { fail_test "$name" "decision absent"; return; }
  [ -f "$repo/untracked.txt" ] || { fail_test "$name" "untracked file removed"; return; }
  pass "$name"
}

test_cross_owner_checkpoint_configuration() {
  local name="cross-owner checkpoint configuration is a decision"
  local repo="$TEST_ROOT/cross-owner" out="$TEST_ROOT/cross-owner.json" rc
  git_init_repo "$repo"
  git_commit_file "$repo"
  add_standard_remotes "$repo" cross-owner
  git -C "$repo" config remote.upstream.pushurl DISABLED
  mkdir -p "$repo/.entire"
  cat > "$repo/.entire/settings.json" <<'EOF'
{"enabled":true,"strategy_options":{"checkpoint_remote":{"provider":"github","repo":"entireio/cli-checkpoints"}}}
EOF
  run_capture "$out" bash "$SCRIPT" check --repo "$repo" --format json
  rc=$?
  [ "$rc" -eq 3 ] || { fail_test "$name" "check exit was $rc"; return; }
  assert_eq "true" "$(jq -r '.entire.checkpoint_owner_mismatch' "$out")" "owner mismatch" || { fail_test "$name" "mismatch absent"; return; }
  assert_contains "$(jq -r '.plan.decisions[]' "$out")" "resolve_checkpoint_remote_owner_mismatch" "mismatch decision" || { fail_test "$name" "decision absent"; return; }
  pass "$name"
}

test_mirror_planning() {
  local name="mirror topology is identity-checked and planned"
  local repo="$TEST_ROOT/mirror" out="$TEST_ROOT/mirror.json" direct="$TEST_ROOT/direct.json" rc
  git_init_repo "$repo"
  git_commit_file "$repo"
  git -C "$repo" remote add origin entire://api.entire.io/gh/MuskanPaliwal/mirror
  git -C "$repo" remote add github-origin git@github.com:MuskanPaliwal/mirror.git
  git -C "$repo" remote add upstream git@github.com:entireio/mirror.git
  git -C "$repo" config remote.upstream.pushurl DISABLED
  run_capture "$out" bash "$SCRIPT" check --repo "$repo" --format json
  rc=$?
  [ "$rc" -eq 0 ] || { fail_test "$name" "complete mirror exit was $rc"; return; }
  assert_eq "complete" "$(jq -r '.mirror_topology' "$out")" "complete mirror" || { fail_test "$name" "topology wrong"; return; }
  git -C "$repo" remote set-url origin git@github.com:MuskanPaliwal/mirror.git
  run_capture "$direct" bash "$SCRIPT" check --repo "$repo" --format json
  rc=$?
  [ "$rc" -eq 3 ] || { fail_test "$name" "mirror planning exit was $rc"; return; }
  assert_contains "$(jq -r '.plan.decisions[]' "$direct")" "adopt_entire_mirror" "mirror adoption decision" || { fail_test "$name" "adoption absent"; return; }
  run_capture "$direct" bash "$SCRIPT" check --repo "$repo" --format json --mirror-policy optional
  rc=$?
  [ "$rc" -eq 0 ] || { fail_test "$name" "optional mirror policy exit was $rc"; return; }
  pass "$name"
}

test_missing_authentication() {
  local name="missing Entire authentication is explicit"
  local repo="$TEST_ROOT/missing-auth" out="$TEST_ROOT/missing-auth.json" rc
  git_init_repo "$repo"
  git_commit_file "$repo"
  add_standard_remotes "$repo" missing-auth
  git -C "$repo" config remote.upstream.pushurl DISABLED
  FAKE_ENTIRE_AUTH=missing run_capture "$out" bash "$SCRIPT" check --repo "$repo" --format json
  rc=$?
  [ "$rc" -eq 3 ] || { fail_test "$name" "check exit was $rc"; return; }
  assert_eq "not-logged-in" "$(jq -r '.entire.auth' "$out")" "auth state" || { fail_test "$name" "auth wrong"; return; }
  assert_contains "$(jq -r '.plan.decisions[]' "$out")" "authenticate_entire" "auth decision" || { fail_test "$name" "decision absent"; return; }
  pass "$name"
}

test_stale_and_unknown_plan_guards() {
  local name="stale and unknown plans cannot mutate"
  local repo="$TEST_ROOT/guards" plan="$TEST_ROOT/guards.plan" unknown="$TEST_ROOT/unknown.plan" before after fingerprint
  git_init_repo "$repo"
  git_commit_file "$repo"
  add_standard_remotes "$repo" guards
  bash "$SCRIPT" plan --repo "$repo" > "$plan" || true
  git -C "$repo" remote set-url upstream git@github.com:entireio/guards-renamed.git
  before=$(repo_snapshot "$repo")
  if bash "$SCRIPT" apply --repo "$repo" --plan "$plan" --yes --allow disable_upstream_push >/dev/null 2>&1; then
    fail_test "$name" "stale plan applied"; return
  fi
  after=$(repo_snapshot "$repo")
  assert_eq "$before" "$after" "stale plan must not mutate" || { fail_test "$name" "stale plan mutated"; return; }
  bash "$SCRIPT" plan --repo "$repo" > "$plan" || true
  fingerprint=$(awk '$1 == "fingerprint" { print $2 }' "$plan")
  {
    printf 'ENTIRE_REPOSITORY_BOOTSTRAP_PLAN_V1\n'
    printf 'fingerprint %s\n' "$fingerprint"
    printf 'safe run_arbitrary_shell\n'
  } > "$unknown"
  before=$(repo_snapshot "$repo")
  if bash "$SCRIPT" apply --repo "$repo" --plan "$unknown" --yes --allow run_arbitrary_shell >/dev/null 2>&1; then
    fail_test "$name" "unknown action applied"; return
  fi
  after=$(repo_snapshot "$repo")
  assert_eq "$before" "$after" "unknown action must not mutate" || { fail_test "$name" "unknown plan mutated"; return; }
  pass "$name"
}

test_new_directory() {
  local name="new directory is inspected without initialization"
  local repo="$TEST_ROOT/new-directory" out="$TEST_ROOT/new.json" rc
  mkdir -p "$repo"
  run_capture "$out" bash "$SCRIPT" check --repo "$repo" --format json
  rc=$?
  [ "$rc" -eq 3 ] || { fail_test "$name" "check exit was $rc"; return; }
  assert_eq "false" "$(jq -r '.repository.is_git' "$out")" "is git" || { fail_test "$name" "wrong git state"; return; }
  assert_contains "$(jq -r '.plan.decisions[]' "$out")" "initialize_repository" "init decision" || { fail_test "$name" "decision absent"; return; }
  [ ! -e "$repo/.git" ] || { fail_test "$name" "repository was initialized"; return; }
  pass "$name"
}

