		Name:          name,
		DisplayName:   string(ag.Type()),
		Model:         effectiveModel,
		TextGenerator: textGenerator,
		Streaming:     streaming,
		Generator: &summarize.TextGeneratorAdapter{
			TextGenerator: textGenerator,
			Model:         effectiveModel,
		},
	}, nil
