	case len(changes) > 0:
		fmt.Fprintf(errW, "%d of %d runner(s) would change", len(changes), inScope)
		if skipped > 0 {
			fmt.Fprintf(errW, ", %d proposal(s) rejected", skipped)
		}
		fmt.Fprintln(errW, ". Nothing was written — re-run with --yes to apply.")
